// Regenerate guardd/tests/fixtures/actor-vectors.json:
//   node guardd/tests/fixtures/gen-actor-vectors.mjs "$PWD" > guardd/tests/fixtures/actor-vectors.json
// The hook's keyed actor (cli/content-hash.mjs actorHash: hashWithKey(deriveKey(installToken), `${user}@${host}`))
// for fixed (installToken, user, host) triples. guardd/src/policy.rs derive_actor is tested against the same file
// (and test/guardd-actor-parity.test.mjs checks the Node side), so the actor guardd derives from an IPC peer is
// byte-identical to the one that peer's hook claims.
const ch = await import(process.argv[2] + "/cli/content-hash.mjs");
const triples = [
  ["tok-acme", "user501", "test-host"],
  ["tok-acme", "user502", "test-host"],
  ["tok-guardd-e2e", "alice", "Alices-MacBook-Pro.local"],
  ["0b6f4e1c-2d4a-4f3e-9c1b-7a2e5d8f9a01", "first.last", "LAPTOP-7Q2K"],
  ["tok-acme", "JOSÉ-ñ", "host-ü"],
  ["tok-acme", "a@b", "c"],
];
const vectors = triples.map(([installToken, user, host]) => ({ installToken, user, host, actor: ch.hashWithKey(ch.deriveKey(installToken), `${user}@${host}`) }));
console.log(JSON.stringify({ comment: "generated by cli/content-hash.mjs hashWithKey(deriveKey(installToken), `${user}@${host}`), the body of actorHash", keyLabel: ch.KEY_LABEL, noKey: ch.NO_KEY, vectors }, null, 1));
